      description: "false",
    }).build().pass;
    let depositedNumber: number = l({
      logic: () => 0,
      description: "0",
    }).build().pass;
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
      l({
        logic: () => StandardOPs.oclIsUndefined(this.InputCard) === false,
        description: "InputCard.oclIsUndefined()=false",
      })
        .and({
          logic: () => this.PasswordValidated === true,
          description: "PasswordValidated=true",
        })
        .and({
          logic: () => this.CardIDValidated === true,
          description: "CardIDValidated=true",
        })
        .and({
          logic: () => StandardOPs.oclIsUndefined(inputCard) === false,
          description: "inputCard.oclIsUndefined()=false",
        })
        .build();
    if (!isPreconditionPass) {
      throw new PreconditionError(preconditionErrorMessage);
    }
    /*Precondition End*/

    /*Postcondition Start*/
    return l({
      execute: () => (inputCard = new BankCard()),
      description: "inputCard.oclIsNew()",
    })
      .and({
        execute: () => (inputCard.Balance = 0),
        description: "inputCard.Balance=0",
      })
      .and({
        execute: () => (inputCard.CardStatus = CardStatus.SUSPEND),
        description: "inputCard.CardStatus=CardStatus::SUSPEND",
      })
      .and({
        execute: () => (inputCard.Password = 0),
        description: "inputCard.Password=0",
      })
      .and({
        execute: () => (depositedNumber = 0),
        description: "depositedNumber=0",
      })
      .and({
        execute: () => isNew,
        description: "result=isNew",
      })
      .build().value;
    /*Postcondition End*/
  }
}
